// Normalize the incoming webhook request into a stable shape.
const item = $input.first().json;

// Webhook payload lives under body; fall back to root for direct executions.
const src = (item && typeof item.body === 'object' && item.body !== null) ? item.body : item;

const workspace_id = (src && src.workspace_id !== undefined) ? src.workspace_id : null;
const research_question = (src && src.research_question !== undefined) ? src.research_question : null;
const gap_analysis = (src && src.gap_analysis !== undefined) ? src.gap_analysis : null;
const synthesis = (src && src.synthesis !== undefined) ? src.synthesis : null;

return [
  {
    json: {
      workspace_id,
      research_question,
      // Preserve the complete gap_analysis object (gap_summary, research_gaps, research_opportunities).
      gap_analysis,
      // Preserve the research synthesis for downstream AI reasoning.
      synthesis,
    },
  },
];

// Validate the normalized input. Produce a normalized validation object.
const data = $input.first().json || {};

const workspace_id = data.workspace_id;
const research_question = data.research_question;
const gap_analysis = data.gap_analysis;
const synthesis = data.synthesis;

const errors = [];

if (workspace_id === undefined || workspace_id === null || workspace_id === '') {
  errors.push('workspace_id is required');
}

if (typeof research_question !== 'string' || research_question.trim() === '') {
  errors.push('research_question must be a non-empty string');
}

const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);

if (!isObject(gap_analysis)) {
  errors.push('gap_analysis must be an object');
} else {
  if (gap_analysis.gap_summary === undefined || gap_analysis.gap_summary === null) {
    errors.push('gap_analysis.gap_summary is required');
  }
  if (gap_analysis.research_gaps === undefined || gap_analysis.research_gaps === null) {
    errors.push('gap_analysis.research_gaps is required');
  } else if (!Array.isArray(gap_analysis.research_gaps)) {
    errors.push('gap_analysis.research_gaps must be an array');
  } else if (gap_analysis.research_gaps.length < 1) {
    errors.push('gap_analysis.research_gaps must contain at least one item');
  }
}

const is_valid = errors.length === 0;

if (is_valid) {
  return [
    {
      json: {
        workspace_id,
        research_question,
        gap_analysis,
        synthesis,
        is_valid: true,
        error: null,
      },
    },
  ];
}

return [
  {
    json: {
      workspace_id: null,
      research_question: null,
      gap_analysis: null,
      synthesis: null,
      is_valid: false,
      error: errors.join('; '),
    },
  },
];

