// Parse and validate the AI output into a stable direction_analysis structure.
const aiJson = $input.first().json || {};

// Carry context forward from the validation step.
const validated = $('Validate Direction Input').first().json || {};
const workspace_id = validated.workspace_id !== undefined ? validated.workspace_id : null;
const research_question = validated.research_question !== undefined ? validated.research_question : null;
const synthesis = validated.synthesis !== undefined ? validated.synthesis : null;
const gap_analysis = validated.gap_analysis !== undefined ? validated.gap_analysis : null;

const fail = (msg) => [
  {
    json: {
      workspace_id,
      research_question,
      synthesis,
      gap_analysis,
      direction_analysis: null,
      is_valid: false,
      error: msg,
    },
  },
];

const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);

// Extract raw content from the OpenAI (v1.8, simplified) response.
let raw = aiJson.message && aiJson.message.content !== undefined ? aiJson.message.content : aiJson;

let parsed;
try {
  if (isObject(raw)) {
    parsed = raw;
  } else if (typeof raw === 'string') {
    let text = raw.trim();
    if (text.startsWith('\`\`\`')) {
      text = text.replace(/^\`\`\`[a-zA-Z]*\s*/, '').replace(/\`\`\`\s*$/, '').trim();
    }
    parsed = JSON.parse(text);
  } else {
    return fail('AI response was empty or in an unexpected format');
  }
} catch (e) {
  return fail('Failed to parse AI response as JSON: ' + e.message);
}

if (!isObject(parsed)) {
  return fail('Parsed AI response is not an object');
}

const directions = parsed.research_directions;
if (!Array.isArray(directions) || directions.length < 1) {
  return fail('research_directions must be a non-empty array');
}

const nonEmptyString = (v) => typeof v === 'string' && v.trim() !== '';

for (let i = 0; i < directions.length; i++) {
  const d = directions[i];
  if (!isObject(d)) {
    return fail('Direction at index ' + i + ' is not an object');
  }
  if (!nonEmptyString(d.title)) {
    return fail('Direction at index ' + i + ' has an empty title');
  }
  if (!nonEmptyString(d.research_question)) {
    return fail('Direction at index ' + i + ' has an empty research_question');
  }
}

const direction_analysis = {
  direction_summary: nonEmptyString(parsed.direction_summary) ? parsed.direction_summary : '',
  research_directions: directions.map((d) => ({
    title: d.title,
    research_question: d.research_question,
    rationale: d.rationale !== undefined ? d.rationale : '',
    expected_contribution: d.expected_contribution !== undefined ? d.expected_contribution : '',
  })),
};

return [
  {
    json: {
      workspace_id,
      research_question,
      synthesis,
      gap_analysis,
      direction_analysis,
      is_valid: true,
      error: null,
    },
  },
];

const data = $input.first().json || {};
return [
  {
    json: {
      success: true,
      message: 'Research directions generated successfully',
      workspace_id: data.workspace_id !== undefined ? data.workspace_id : null,
      research_question: data.research_question !== undefined ? data.research_question : null,
      direction_analysis: data.direction_analysis !== undefined ? data.direction_analysis : null,
    },
  },
];

const data = $input.first().json || {};
return [
  {
    json: {
      success: false,
      message: 'Research direction generation failed',
      workspace_id: data.workspace_id || null,
      research_question: data.research_question || null,
      error: data.error || 'Unknown direction analysis error',
    },
  },
];

const data = $input.first().json || {};
return [
  {
    json: {
      success: false,
      message: 'Invalid research direction input',
      workspace_id: data.workspace_id || null,
      research_question: data.research_question || null,
      error: data.error || 'Invalid input',
    },
  },
];
